-- Workforce Hub: referrals from the organization to a partner, about a need (not a named person). Additive. Applied 2026-11-18.
CREATE TABLE IF NOT EXISTS "PartnerReferral" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "partnerId" TEXT NOT NULL, "title" TEXT NOT NULL, "message" TEXT, "cohortName" TEXT, "offeringTitle" TEXT, "people" INTEGER, "dueDate" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'SENT', "answerNote" TEXT, "answeredAt" TIMESTAMP(3), "answeredBy" TEXT, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PartnerReferral_pkey" PRIMARY KEY ("id"), CONSTRAINT "PartnerReferral_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "Institution"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "PartnerReferral_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "EcosystemPartner"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "PartnerReferral_institutionId_createdAt_idx" ON "PartnerReferral"("institutionId", "createdAt");
CREATE INDEX IF NOT EXISTS "PartnerReferral_partnerId_idx" ON "PartnerReferral"("partnerId");
